.vp_finite<-function(value){if(is.list(value)){for(v in value).vp_finite(v)}else if(is.numeric(value)&&any(!is.finite(value))).cr_error('VALIDATION_NUMERICAL','Policy metric outside finite numeric range');invisible(NULL)}
decision_policy_backtest<-function(evaluated_grid,grid_inputs,historical_cases,design,reference_candidate_id,uncertainty='none',cluster_resamples=NULL,confidence_level=.95,tolerance=1e-10,context=NULL){
 d<-.vb_design(design,context);tol<-.vb_number(tolerance,'tolerance',0);grid<-.cr_dec_checked(evaluated_grid,'DecisionGrid');inputs<-grid_inputs;if(!.cr_object(inputs)||'context'%in%names(inputs)).cr_error('VALIDATION_POLICY','Original grid inputs without context required');if(!identical(inputs$evaluation_cutoff,d$evaluation_cutoff)).cr_error('VALIDATION_POLICY','Grid and design cutoffs differ');profile<-inputs$evaluation_profile;version<-if(is.null(d$policy_target_contract_version))'1.0'else d$policy_target_contract_version;profile_version<-if(is.null(profile$target_contract_version))'1.0'else profile$target_contract_version;bound_target<-d$target;if(!(version%in%c('1.0','1.1'))||!identical(version,profile_version)).cr_error('VALIDATION_POLICY','Policy target contract versions must explicitly match');if(identical(version,'1.1')){if(!identical(d$performance_origin,'first_draw_at')).cr_error('VALIDATION_POLICY','Version1.1 requires actual first-draw performance origin');bound_target$performance_origin<-d$performance_origin};if(.cr_hash(profile$target)!=.cr_hash(bound_target)||!identical(profile$currency,d$currency)||!identical(profile$split_id,d$split_id)||!identical(profile$data_fingerprint,d$data_fingerprint)).cr_error('VALIDATION_POLICY','Exact currency, target, split and data binding required');replay<-do.call(evaluate_decision_grid,inputs)$value;violations<-list();mismatch<-.va_differences(grid,replay,tol);if(length(mismatch))violations[[1]]<-list(code='FROZEN_GRID_RECONCILIATION',case_id=NULL,paths=as.list(mismatch));rows<-.vb_records(historical_cases,d);hm<-.vs_index(rows,'case_id','historical cases')$index;cm<-.vs_index(inputs$cases,'case_id','grid cases')$index;pm<-.vs_index(replay$candidates,'candidate_id','grid candidates')$index;if(!setequal(names(hm),names(cm))||!(reference_candidate_id%in%names(pm))).cr_error('VALIDATION_POLICY','Exact paired historical population and existing reference required');if(!length(rows)).cr_error('VALIDATION_POLICY','Nonempty historical cases required');entity_clusters<-list();for(r in rows){if(!is.null(entity_clusters[[r$entity_id]])&&!identical(entity_clusters[[r$entity_id]],r$cluster_id)).cr_error('VALIDATION_DEPENDENCE','Repeated entity cannot cross sampling clusters');entity_clusters[[r$entity_id]]<-r$cluster_id};draws<-.vb_draws(uncertainty,cluster_resamples,rows,confidence_level);outcomes<-setNames(inputs$observed_outcomes,vapply(inputs$observed_outcomes,function(r)r$case_id,character(1)));ci<-list();traces<-list();for(r in inputs$candidate_inputs){if(is.null(ci[[r$candidate_id]]))ci[[r$candidate_id]]<-list();ci[[r$candidate_id]][[r$case_id]]<-r};for(p in replay$candidates)traces[[p$candidate_id]]<-setNames(p$decisions,vapply(p$decisions,function(t)t$case_id,character(1)));audits<-list();violation<-function(code,key,paths=list()){violations[[length(violations)+1L]]<<-list(code=code,case_id=key,paths=as.list(paths))}
 for(row in rows){key<-row$case_id;cid<-row$historical_candidate_id;case<-cm[[key]];if(!(cid%in%names(pm))||row$as_of!=case$decision_date||.vb_number(if(is.null(row$weight))1 else row$weight,'weight',0)!=case$weight).cr_error('VALIDATION_POLICY','Historical candidate, date and weights must bind grid case');t<-traces[[cid]][[key]];recorded<-.cr_dec_checked(row$historical_decision,'DecisionArtifact');changed<-.va_differences(recorded,t$decision,tol);if(length(changed))violation('HISTORICAL_DECISION_RECONCILIATION',key,changed);if('POLICY_NOT_EFFECTIVE'%in%unlist(t$decision$findings))violation('HISTORICAL_POLICY_NOT_EFFECTIVE',key);for(field in c('offered','taken_up'))if(!is.logical(row[[field]])||length(row[[field]])!=1L||is.na(row[[field]])).cr_error('VALIDATION_POLICY','Explicit offer and take-up stages required');o<-outcomes[[key]];if(is.null(o)).cr_error('VALIDATION_POLICY','Explicit actual funding or no-funding record required');if(row$taken_up&&!row$offered||o$funded&&!row$taken_up).cr_error('VALIDATION_POLICY','Take-up requires offer; funding requires take-up');stage_known<-.cr_data_date(row$stages_known_at,'stages_known_at');if(stage_known<.cr_data_date(row$as_of,'as_of')).cr_error('VALIDATION_POLICY','Actual stage knowledge cannot predate decision');visible<-stage_known<=.cr_data_date(d$evaluation_cutoff,'cutoff')&&(!o$funded||o$funding_known_at<=d$evaluation_cutoff);terms<-ci[[cid]][[key]]$offer;limit<-NULL;booked<-NULL;if(row$offered){if(visible&&t$action!='APPROVE')violation('OFFER_WITHOUT_POLICY_APPROVAL',key);limit<-.vb_number(row$offered_limit,'offered_limit',0);if(!.cr_object(terms)||!.cr_object(terms$contract_terms)).cr_error('VALIDATION_POLICY','Explicit frozen offer contract terms required');cap<-.vb_number(terms$contract_terms$limit,'contract limit',0);if(visible&&limit>cap+tol)violation('OFFER_LIMIT_EXCEEDED',key)}else if(!is.null(row$offered_limit)).cr_error('VALIDATION_POLICY','Unoffered limit must be null');if(o$funded){booked<-.vb_number(row$booked_amount,'booked_amount',0);if(visible&&booked>limit+tol)violation('BOOKED_LIMIT_EXCEEDED',key);if(visible&&!identical(o$booked_offer_hash,t$offer_hash))violation('BOOKED_TERMS_DIFFER_FROM_HISTORICAL_OFFER',key)}else if(!is.null(row$booked_amount)).cr_error('VALIDATION_POLICY','Unfunded booked amount must be null');cost<-NULL;if(!is.null(row$application_cost)){cost<-.vb_number(row$application_cost,'application_cost',0);if(!isTRUE(row$cost_complete)||.cr_data_date(row$cost_known_at,'cost_known_at')>.cr_data_date(d$evaluation_cutoff,'cutoff'))cost<-NULL};matched<-Filter(function(s)s$case_id==key,pm[[cid]]$observed_outcomes$case_status)[[1]]$status;audits[[length(audits)+1L]]<-list(case_id=key,cluster_id=row$cluster_id,weight=case$weight,historical_candidate_id=cid,action=t$action,offered=row$offered,taken_up=row$taken_up,funded=o$funded,stage_evidence_visible=visible,offered_limit=limit,booked_amount=booked,known_complete_application_cost=cost,mature_matched_funded=matched=='MATURE_MATCHED_FUNDED',observed_default=if(matched=='MATURE_MATCHED_FUNDED')as.numeric(o$defaulted)else NULL,observed_loss=if(matched=='MATURE_MATCHED_FUNDED')o$economic_loss else NULL,policy_findings=t$decision$findings)}
 measure<-function(mult=NULL){weights<-setNames(vapply(seq_along(rows),function(i){r<-rows[[i]];(if(is.null(r$weight))1 else r$weight)*if(is.null(mult))1 else mult[i]},numeric(1)),vapply(rows,function(r)r$case_id,character(1)));total<-sum(weights);paired<-structure(list(),names=character());scenarios<-list();for(cid in names(pm)){counts<-setNames(rep(0,4),c('APPROVE','REFER','DECLINE','BLOCKED'));el<-ep<-ead<-0;identified<-TRUE;for(key in names(weights)){w<-weights[[key]];t<-traces[[cid]][[key]];r<-ci[[cid]][[key]];a<-t$action;counts[[a]]<-counts[[a]]+w;if(a=='APPROVE'){offer<-r$offer;if(offer$support_status!='SUPPORTED'&&w>0)identified<-FALSE else if(offer$support_status=='SUPPORTED'){el<-el+w*offer$takeup_probability*offer$conditional_booked_expected_loss;ep<-ep+w*(offer$takeup_probability*offer$conditional_booked_npv-offer$offer_cost);ead<-ead+w*offer$takeup_probability*offer$ead}}else ep<-ep-w*r$nonapproval_costs[[a]]};scenarios[[cid]]<-setNames(lapply(counts,function(v)if(total>0)v/total else NULL),c('approval_rate','refer_rate','decline_rate','blocked_rate'));scenarios[[cid]]$expected_loss_per_application<-if(total>0&&identified)el/total else NULL;scenarios[[cid]]['expected_loss_per_application']<-list(if(total>0&&identified)el/total else NULL);scenarios[[cid]]['expected_npv_per_application']<-list(if(total>0&&identified)ep/total else NULL);scenarios[[cid]]['expected_funded_ead_per_application']<-list(if(total>0&&identified)ead/total else NULL)};ref<-scenarios[[reference_candidate_id]];for(cid in names(scenarios))for(k in names(scenarios[[cid]])){v<-scenarios[[cid]][[k]];paired[paste(cid,k,sep='|')]<-list(if(is.null(v)||is.null(ref[[k]]))NULL else v-ref[[k]])};factual<-list();visible<-Filter(function(a)a$stage_evidence_visible,audits);den<-sum(vapply(visible,function(a)weights[[a$case_id]],numeric(1)));for(field in c('offered','taken_up','funded'))factual[paste0(field,'_rate')]<-list(if(den>0)sum(vapply(visible,function(a)weights[[a$case_id]]*a[[field]],numeric(1)))/den else NULL);mature<-Filter(function(a)a$mature_matched_funded,audits);mass<-sum(vapply(mature,function(a)weights[[a$case_id]],numeric(1)));factual$visible_stage_weight<-den;factual$mature_matched_funded_weight<-mass;factual['observed_pd']<-list(if(mass>0)sum(vapply(mature,function(a)weights[[a$case_id]]*a$observed_default,numeric(1)))/mass else NULL);factual['observed_mean_loss']<-list(if(mass>0)sum(vapply(mature,function(a)weights[[a$case_id]]*a$observed_loss,numeric(1)))/mass else NULL);costs<-Filter(function(a)!is.null(a$known_complete_application_cost),audits);cost_mass<-sum(vapply(costs,function(a)weights[[a$case_id]],numeric(1)));factual$known_complete_cost_weight<-cost_mass;factual['mean_application_cost']<-list(if(cost_mass>0)sum(vapply(costs,function(a)weights[[a$case_id]]*a$known_complete_application_cost,numeric(1)))/cost_mass else NULL);.vp_finite(list(scenarios,paired,factual));list(scenario=scenarios,paired=paired,factual=factual)}
 measured<-measure();bands<-.vb_bands(if(is.null(draws))NULL else lapply(draws,function(x)measure(x)$paired),confidence_level);for(cid in names(pm))for(check in pm[[cid]]$constraints)if(check$status=='VIOLATED')violation('CANDIDATE_SCENARIO_CONSTRAINT_VIOLATED',NULL,c(cid,check$constraint_id));counts<-table(vapply(violations,function(v)v$code,character(1)));value<-list(artifact_type='ValidationResult',design=d,decision=list(status=if(length(violations))'BLOCKED'else'NOT_ASSESSED',rule='RECONCILIATION_AND_DECLARED_SCENARIO_CONSTRAINTS'),metrics=list(factual=measured$factual,candidate_scenario=measured$scenario,paired_candidate_minus_reference=measured$paired),uncertainty=bands,p_value=NULL,applicability='APPLICABLE',violations=violations,violation_counts=structure(as.list(as.numeric(counts)),names=as.character(names(counts))),case_audits=audits,dependence=list(repeated_entity_rows=length(rows)-length(entity_clusters),cluster_count=length(unique(unlist(entity_clusters))),sampling_unit='DECLARED_WHOLE_CLUSTER'),candidate_observed_scopes=setNames(lapply(pm,function(p)p$observed_outcomes),names(pm)),candidate_constraints=setNames(lapply(pm,function(p)p$constraints),names(pm)),counterfactual=list(applicability='NOT_IDENTIFIED',full_policy_causal_value=NULL,reason='Frozen offer assumptions and matching factual subsets do not identify unobserved actions, changed terms, take-up or policy selection effects'),input_fingerprint=.cr_hash(list(grid_inputs=grid_inputs,historical_cases=historical_cases)),recomputed_grid_hash=replay$sha256,fitted_any_model=FALSE,executed_lending_action=FALSE);.cr_result(value,'validation.decision_policy_backtest','validation_metrics',context,limitations='Only local frozen policy evaluation is replayed. Observed risks belong to mature funded cases at identical booked offer hashes; approved but unfunded cases have no credit labels. Price/limit changes remain scenarios, not causal policy evidence. Intervals condition on frozen policies, offer assumptions and supplied sampling clusters.')
}
